query ($assetGroupId: String!){
  assetGroup(
    where:{
      id:{ _eq: $assetGroupId}
    }
  ) {
	  edges {
	    node {
	      id
        assetGroupDesign{
          assetGroupDesignAssetDesigns(
            where:{
              active:{ _eq: true}
            }
          ){
            edges{
              node{
                id
                quantity
                note
                assetDesignId
                assetDesign{
                  id
                  name
                }
              }
            }
          }
        }
        assets {
          edges {
            node {
              assetDesignId
              _aggregate{
                number{
                  count
                }
              }

            }
          }
        }
	    }
	  }
	}
}
